// Lineage Policy helper (blast radius)
// The more tables depend on this one, the riskier the action.

const input = $input.first().json;
const dh = input.datahub_context || input;

const dataset = dh.dataset || 'unknown dataset';
const downstream = (typeof dh.downstream_count === 'number') ? dh.downstream_count : 0;

// Thresholds you can tune later.
const HIGH_BLAST = 50;   // 50+ dependents = very risky
const SOME_BLAST = 5;    // 5-49 dependents = needs a look

let verdict = 'approve';
let reason = '';

if (downstream >= HIGH_BLAST) {
  verdict = 'deny';
  reason = "Lineage Policy: '" + dataset + "' has " + downstream + " downstream tables — huge blast radius, blocked.";
} else if (downstream >= SOME_BLAST) {
  verdict = 'human_review';
  reason = "Lineage Policy: '" + dataset + "' has " + downstream + " downstream tables — needs a human to review.";
} else {
  verdict = 'approve';
  reason = "Lineage Policy: '" + dataset + "' has only " + downstream + " downstream tables — low blast radius.";
}

return { json: { policy: 'lineage', verdict, reason } };
